INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261105-celtics-bucks', 'celtics-beat-bucks-109-102-paul-george-derrick-white-tatum-rests', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Paul George and Derrick White carry the Celtics past the Bucks 109-102 with Jayson Tatum resting', 'Boston blew a 22-point lead and Milwaukee briefly went ahead, but White scored seven of the Celtics'' last 10 points at TD Garden on Wednesday, Nov. 4. Boston is 6-2.', 'The Celtics nearly lost a big lead without Jayson Tatum, but held on to beat the Milwaukee Bucks 109-102 at TD Garden on Wednesday night, Nov. 4.

Paul George scored 25 points with five 3-pointers and four steals. Derrick White added 24 points and seven assists, the Associated Press reported via CBS Boston. Tatum sat out to rest, his first missed game of the season. He had scored 19 points in Monday''s 109-93 loss at Houston.

## How it went

- Boston held Milwaukee to 14 first-quarter points, the Celtics'' best defensive quarter of the season, according to the Celtics'' recap on NBA.com. Boston led by 21 at halftime and by as many as 22.
- Tyler Herro scored 18 of his 25 points in the third quarter as the Bucks went on a 26-12 run, the AP reported.
- Nate Ament''s free throw gave Milwaukee its first lead, 92-91, in the fourth. After the Bucks tied it at 97, Neemias Queta''s driving layup off a George pass put Boston ahead for good.
- White scored 11 points in the fourth quarter, including 7-for-7 free throws, and seven of Boston''s last 10 points, NBA.com reported.

Boston won the rebounding battle 54-45. Queta (12), Baylor Scheierman (11) and Mitchell Robinson (10) all reached double figures on the boards. Payton Pritchard missed the fourth quarter with a right eye abrasion, the AP reported.

The Celtics are 6-2 and 5-0 at home. Milwaukee fell to 1-7. Jaime Jaquez Jr. scored 18 for the Bucks and Ryan Rollins added 13.

## Next

Boston starts a four-game road trip at Charlotte on Friday, Nov. 6.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/8/8c/Zakim_bridge_and_the_TD_Garden_(9097726826).jpg', 'The Zakim Bridge and TD Garden, home of the Celtics, in Boston (file). Photo: Flickr via Wikimedia Commons, Creative Commons license (editor: confirm photographer name and license on the Commons file page before approving)', 'licensed', 'newsroom', 'content/2026-11-05.sql', 7, 0, 'newsroom-assistant', '2026-11-05T11:00:00.000Z', '2026-11-05T11:00:00.000Z');
