INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261105-patriots-packers-injuries', 'drake-maye-full-practice-shoulder-aj-brown-hunter-henry-out-packers', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Drake Maye practices fully with a shoulder injury as A.J. Brown and Hunter Henry sit out before the Packers game', 'The 5-3 Patriots host Green Bay on Sunday, Nov. 8. Mack Hollins was back at practice in a limited role, and the trade deadline is Tuesday, Nov. 10.', 'Drake Maye was a full participant at Patriots practice on Wednesday, Nov. 4, even though he is listed with a right shoulder injury, according to the team''s official injury report. The Patriots host the Green Bay Packers on Sunday, Nov. 8.

## Patriots practice report, Wednesday, Nov. 4

- **Did not practice:** WR A.J. Brown (ankle/knee), TE Hunter Henry (foot), DT Christian Barmore (illness), RB TreVeyon Henderson (illness)
- **Limited:** S Kevin Byard III (chest), CB Carlton Davis III (neck), WR Mack Hollins (calf), OLB Gabe Jacas (knee), LB Dre''Mont Jones (shoulder/knee), T Morgan Moses (foot), C/G Greg Van Roten (hamstring)
- **Full:** QB Drake Maye (right shoulder)

Hollins has been on injured reserve since a calf injury against Buffalo in Week 4. NFL Network''s Ian Rapoport reported that he would return to practice, according to Athlon Sports, but he has not been activated yet. Brown also missed the 24-19 comeback win over Miami on Sunday, Nov. 1, and his status is still uncertain.

## Green Bay''s list

Linebacker Zaire Franklin (shin), offensive linemen Travis Glover (knee) and Sean Rhyan (ankle) and tight end Josh Whyle (concussion) did not practice for the Packers. Edge rusher Micah Parsons (knee), receiver Christian Watson (rib), cornerback Keisean Nixon (shoulder), guard Aaron Banks (knee) and running back Chris Brooks (ankle) were limited.

Green Bay''s defense allows 204 passing yards a game, eighth-fewest in the league, Athlon noted.

## Deadline watch

The NFL trade deadline is 4 p.m. ET on Tuesday, Nov. 10, according to Yahoo Sports. Yahoo Sports cited a report by Albert Breer that Barmore is on the trade block.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/3/3c/Aerial_Photograph_of_Boston,_Massachusetts_-_NARA_-_7455642.jpg', 'Aerial view of Boston, Massachusetts (file). Photo: U.S. National Archives via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-05.sql', 6, 0, 'newsroom-assistant', '2026-11-05T11:00:00.000Z', '2026-11-05T11:00:00.000Z');
