INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261105-nhl-wednesday', 'senators-edge-sabres-kempe-hat-trick-kings-panthers-beat-blackhawks-bruins-pittsburgh', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Amadio''s late goal lifts Ottawa past Buffalo, and Kempe''s hat trick powers the Kings to a 7-2 win over San Jose', 'Results from Wednesday, Nov. 4, around the NHL. The Bruins play at Pittsburgh on Thursday, Nov. 5, with Frederic Brunet expected back in the lineup.', 'Here are the results from Wednesday night, Nov. 4, around the NHL.

## Senators 2, Sabres 1

Ottawa scored twice in the third period to win in Buffalo, NHL.com reported. Peyton Krebs gave the Sabres a 1-0 lead in the second when a Tage Thompson shot deflected off his leg. Shane Pinto backhanded in a rebound to tie it at 11:33 of the third. At 16:51, Michael Amadio one-timed a Tim Stutzle pass for the winner.

Samuel Ersson made 24 saves for Ottawa (10-6-1). Colten Ellis stopped 28 for Buffalo (7-5-3), and the loss ended the Sabres'' three-game winning streak.

## Kings 7, Sharks 2

Adrian Kempe scored three goals and added an assist in his return from injury. Quinton Byfield scored twice on the power play, and Artemi Panarin had four assists, NHL.com reported. It was Kempe''s fifth NHL hat trick, which ties him for ninth in Kings history. Darcy Kuemper made 30 saves. Macklin Celebrini scored his sixth goal of the season for San Jose (7-9-1), which has lost three straight. Los Angeles is 5-7-2.

## Panthers 5, Blackhawks 3

Sandis Vilmanis scored twice for Florida, and Sam Reinhart added an empty-net goal with 1:27 left, ESPN reported. Frank Nazar scored twice for Chicago in the third, once short-handed, to make it close. Florida is 9-5-2. Chicago is 4-11-1 and has not won on the road (0-6-1).

## Bruins next

The Bruins play at Pittsburgh on Thursday, Nov. 5. Defenseman Frederic Brunet is expected to return after three straight games as a healthy scratch, Boston Hockey Now reported. Matt Poitras, who broke his nose against Vegas on Monday, Nov. 2, is a game-time decision.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/d/df/Ice_hockey_1922.jpg', 'An ice hockey game in 1922 (historic file photo). Photo: Wikimedia Commons, public domain (editor: confirm the source on the Commons file page)', 'public_domain', 'newsroom', 'content/2026-11-05.sql', 5, 0, 'newsroom-assistant', '2026-11-05T11:00:00.000Z', '2026-11-05T11:00:00.000Z');
